/////////////////
// Summary:
// Create a new Realtime API call over WebRTC and receive the SDP answer needed
// to complete the peer connection.
//
pub fn @"create-realtime-call"(client: *Client, requestBody: []const u8) !Owned([]const u8) {
    var result = try @"create-realtime-callResult"(client, requestBody);
    switch (result) {
        .ok => |ok| return ok,
        .api_error => |*err| {
            err.deinit();
            return error.ResponseError;
        },
        .parse_error => |*err| {
            err.raw.deinit();
            return error.ResponseParseError;
        },
    }
}

pub fn @"create-realtime-callRaw"(client: *Client, requestBody: []const u8) !RawResponse {
    const allocator = client.allocator;
    var uri_buf: std.Io.Writer.Allocating = .init(allocator);
    defer uri_buf.deinit();
    try uri_buf.writer.print("{s}/realtime/calls", .{client.base_url});
    const payload: ?[]const u8 = requestBody;

    var headers = std.ArrayList(std.http.Header).empty;
    defer headers.deinit(allocator);
    const auth_header = try appendClientHeaders(allocator, &headers, client, "application/sdp", "application/json");
    defer if (auth_header) |value| allocator.free(value);

    if (client.http_observer) |obs| {
        if (obs.onRequest) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), headers.items, payload);
    }

    const uri = try std.Uri.parse(uri_buf.written());
    var response_body: std.Io.Writer.Allocating = .init(allocator);
    defer response_body.deinit();
    const start = std.Io.Clock.awake.now(client.io);
    const result = client.http.fetch(.{
        .location = .{ .uri = uri },
        .method = std.http.Method.POST,
        .extra_headers = headers.items,
        .payload = payload,
        .response_writer = &response_body.writer,
    }) catch |err| {
        if (client.http_observer) |obs| {
            if (obs.onError) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), @errorName(err));
        }
        return err;
    };
    const elapsed_ns = @as(u64, @intCast(start.untilNow(client.io, .awake).nanoseconds));

    const body = try response_body.toOwnedSlice();

    if (client.http_observer) |obs| {
        if (obs.onResponse) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), result.status, &.{}, body, elapsed_ns);
    }

    return .{
        .allocator = allocator,
        .status = result.status,
        .body = body,
    };
}

pub fn @"create-realtime-callResult"(client: *Client, requestBody: []const u8) !ApiResult([]const u8) {
    return parseRawResponse([]const u8, try @"create-realtime-callRaw"(client, requestBody));
}

